    'corrige_intro' => 'Un driver ne se repère pas à un comportement isolé, mais à sa répétition, à son excès et à ce qu’il coûte à la personne ou à l’équipe. Le contexte compte : c’est pourquoi plusieurs cartes acceptent plusieurs réponses, ou « Pas forcément un driver ».',
    'cartes' => [
        1  => ['texte' => 'Le conducteur de travaux retarde pour la 4ᵉ fois l’envoi du planning au client : « Il reste deux incohérences mineures dans les jalons, je préfère corriger avant. » La réunion a lieu dans une heure.', 'accepte' => ['sp'],
             'corrige' => 'Retarder un envoi pour deux incohérences « mineures », à une heure de la réunion : la recherche du zéro défaut passe avant l’échéance. Indice : « je préfère corriger avant ». Feu vert : « C’est assez bien pour être envoyé », quitte à signaler les deux points à reprendre.'],
        2  => ['texte' => 'En réunion de lancement, la cheffe de projet coupe la parole : « Oui, oui, on a compris, on passe au point suivant ? » Elle regarde sa montre.', 'accepte' => ['dt'],
             'corrige' => 'Couper la parole, « oui, oui », regarder sa montre : ce sont les signes les plus visibles du Dépêche-toi. Le coût : les autres se taisent et des informations utiles se perdent dès le lancement. Feu vert : « Prends le temps. »'],
        3  => ['texte' => 'Isolé depuis 3 mois sur un chantier routier enclavé, un chef de chantier répond chaque semaine au téléphone : « Tout va bien ici, on se débrouille. » Les rapports montrent deux semaines de retard.', 'accepte' => ['sf'],
             'corrige' => '« Tout va bien, on se débrouille » alors que les rapports montrent du retard : ne pas demander d’aide et masquer la difficulté, c’est le Sois fort. L’isolement du chantier renforce le réflexe. Feu vert : « Tu as le droit de demander de l’aide. »'],
        4  => ['texte' => 'Le responsable matériel prête la niveleuse à un autre chantier « pour rendre service », alors que son propre chantier en a besoin demain.', 'accepte' => ['fp'],
             'corrige' => 'Rendre service au détriment de son propre chantier : le besoin d’être apprécié passe avant ses priorités. Indice : « pour rendre service ». Feu vert : « Tu peux dire non et rester apprécié. »'],
        5  => ['texte' => '« J’ai passé tout le week-end sur ce dossier d’appel d’offres, c’était vraiment dur… mais il n’est pas encore terminé. »', 'accepte' => ['fe'],
