        6  => ['texte' => 'La contrôleuse de gestion refuse de transmettre la clôture mensuelle tant qu’un écart de 300 € n’est pas expliqué.', 'accepte' => ['sp', 'nd'],
             'corrige' => 'Bloquer toute la clôture pour 300 € : l’exigence de précision l’emporte sur l’enjeu, c’est le Sois parfait. « Pas forcément un driver » est aussi accepté : la rigueur fait partie du métier de contrôleur de gestion. La question à poser : la réaction est-elle proportionnée à l’enjeu ?'],
        7  => ['texte' => 'Au quart d’heure sécurité, le chef d’équipe expédie les consignes en 3 minutes : « Vous connaissez tous, allez, on a du béton à couler. »', 'accepte' => ['dt', 'sf'],
             'corrige' => 'Expédier le quart d’heure sécurité en 3 minutes pour passer au béton : la vitesse avant tout, c’est le Dépêche-toi. Sois fort est aussi accepté : « vous connaissez tous » minimise le risque. Attention à l’enjeu : sur la sécurité, un driver coûte cher.'],
        8  => ['texte' => 'Après la chute d’un outil depuis un échafaudage, le chef d’équipe hausse les épaules : « Ce n’est rien, ça arrive, on continue. » Il ne déclare pas le presque-accident.', 'accepte' => ['sf', 'dt'],
             'corrige' => '« Ce n’est rien, ça arrive » : minimiser et ne rien laisser paraître, c’est le Sois fort. Dépêche-toi est aussi accepté : « on continue ». Un presque-accident non déclaré est une occasion d’apprendre perdue : c’est la carte à discuter en priorité.'],
        9  => ['texte' => 'Un chef de projet répond à chaque demande par « Je vais essayer », puis propose systématiquement la solution la plus compliquée alors qu’une option simple existe.', 'accepte' => ['fe'],
             'corrige' => '« Je vais essayer » est la formule type du Fais des efforts, tout comme choisir la solution compliquée quand une option simple existe. Feu vert : « Fais-le, simplement. »'],
        10 => ['texte' => 'La cheffe de service logistique lance cinq chantiers d’amélioration en même temps (douane, stocks, transport…). Aucun n’aboutit, mais elle répète : « On avance, c’est un vrai combat. »', 'accepte' => ['fe', 'dt'],
             'corrige' => 'Lancer cinq chantiers à la fois sans en finir aucun, en répétant « c’est un vrai combat » : l’effort compte plus que l’aboutissement, c’est le Fais des efforts. Dépêche-toi est aussi accepté : tout mener de front est aussi un signe d’urgence permanente.'],
        11 => ['texte' => 'Le directeur de travaux envoie des mails de trois lignes à 23 h, marqués « URGENT », sans formule de politesse, et relance une heure plus tard.', 'accepte' => ['dt'],
             'corrige' => 'Des mails de trois lignes à 23 h, « URGENT », sans politesse, avec une relance une heure plus tard : tout est urgent, tout de suite, c’est le Dépêche-toi. Le coût : l’équipe ne distingue plus ce qui est vraiment prioritaire.'],
        12 => ['texte' => 'Face au maître d’ouvrage (ministère), un chef de projet accepte une modification de tracé sans évoquer ni le coût ni le délai : « Bien sûr, nous allons nous adapter. »', 'accepte' => ['fp', 'nd'],
             'corrige' => 'Accepter la modification sans évoquer ni coût ni délai, pour préserver la relation : c’est le Fais plaisir. « Pas forcément un driver » est aussi accepté : face à un ministère, la prudence en séance peut être une stratégie. Mais coût et délai devront être posés, et le plus tôt sera le mieux.'],
        13 => ['texte' => 'Le responsable QHSE réécrit lui-même les procédures rédigées par son équipe « pour que ce soit propre », au lieu de leur faire des retours.', 'accepte' => ['sp'],
             'corrige' => 'Réécrire soi-même le travail de l’équipe « pour que ce soit propre » au lieu de faire des retours : c’est le Sois parfait. Le coût : l’équipe ne progresse pas et le manager s’épuise. Feu vert : « C’est assez bien, et je t’explique ce qui manque. »'],
        14 => ['texte' => 'Un chef de chantier nouvellement promu ne pose jamais de questions à son conducteur de travaux, même sur un procédé qu’il ne connaît pas. Il préfère chercher seul, le soir.', 'accepte' => ['sf', 'fe', 'nd'],
             'corrige' => 'Ne jamais poser de question, chercher seul le soir : refuser l’aide, c’est d’abord le Sois fort. Fais des efforts est accepté (se donner du mal plutôt que demander) ; « Pas forcément un driver » aussi : la peur de paraître illégitime est fréquente chez un nouveau promu.'],
        15 => ['texte' => 'Quand on lui demande où en est le dédouanement des matériaux, l’assistant logistique décrit longuement toutes les difficultés rencontrées, sans jamais donner de date de livraison.', 'accepte' => ['fe'],
             'corrige' => 'Décrire longuement les difficultés sans jamais donner de date : le récit de l’effort remplace le résultat, c’est le Fais des efforts. La bonne question à lui poser : « Quelle date, et de quoi as-tu besoin pour la tenir ? »'],
        16 => ['texte' => 'En réunion de chantier, un chef d’équipe ne contredit jamais le directeur devant tout le monde. Il vient le voir seul ensuite pour lui dire que la solution ne marchera pas.', 'accepte' => ['fp', 'nd'],
             'corrige' => 'Ne jamais contredire le directeur en public, de peur de déplaire : c’est le Fais plaisir. « Pas forcément un driver » est aussi accepté : ne pas faire perdre la face à un supérieur en public peut être une stratégie adaptée à la culture, et il finit par dire ce qu’il pense.'],
        17 => ['texte' => 'Pendant la saison des pluies, le conducteur de travaux visite trois chantiers par jour, ne finit aucune réunion assis et donne ses consignes depuis sa voiture.', 'accepte' => ['dt', 'nd'],
             'corrige' => 'Trois chantiers par jour, aucune réunion assis, des consignes depuis la voiture : c’est le Dépêche-toi. « Pas forcément un driver » est aussi accepté : la saison des pluies impose réellement un rythme intense. Toute la question est de savoir si ce rythme dure au-delà de la contrainte.'],
        18 => ['texte' => 'En pleine réorganisation, une DAF pays ne montre aucune émotion devant son équipe : « Les décisions sont prises, on applique. » Elle refuse l’appui proposé par la direction régionale.', 'accepte' => ['sf'],
             'corrige' => 'Ne montrer aucune émotion et refuser l’appui proposé : c’est le Sois fort. En pleine réorganisation, l’équipe a besoin de sentir que sa manager est humaine. Feu vert : « Tu peux montrer ce que tu ressens et accepter de l’aide. »'],
        19 => ['texte' => 'Un chef de chantier n’ose pas refuser les demandes de ses sous-traitants locaux, de peur de « casser la relation ». Il finit par absorber leurs retards.', 'accepte' => ['fp'],
             'corrige' => 'Ne pas oser refuser de peur de « casser la relation », jusqu’à absorber les retards des autres : c’est le Fais plaisir. Feu vert : « Tu peux dire non, la relation y survivra. »'],
        20 => ['texte' => '« Ce béton est conforme, mais je préfère refaire une série d’essais avant le coulage, on ne sait jamais. » Le planning prend 48 heures de retard.', 'accepte' => ['sp', 'nd'],
             'corrige' => 'Refaire des essais sur un béton conforme, « on ne sait jamais », au prix de 48 heures de retard : c’est le Sois parfait. « Pas forcément un driver » est aussi accepté : la prudence sur le béton est un réflexe métier. Le débat porte sur le coût de cette précaution.'],
    ],
];
